    'One file with everything: your hours, team shifts, income, expenses, companies and rates. Download it every month or so and keep it somewhere safe, like Google Drive. If anything is ever lost, it can be put back from this file.':'ملف واحد بكل شيء: ساعاتك وورديات الفريق والدخل والمصروفات والشركات والأسعار. نزّله كل شهر تقريبًا واحفظه في مكان آمن مثل Google Drive. إن ضاع أي شيء يمكن استعادته من هذا الملف.',
