    'Avoid for now':'تجنّبها حاليًا',
    'The seller says yes':'البائع يوافق',
    'Agree the price, closing date and earnest money out loud, then say you will send a simple agreement to sign today. Note the seller’s full legal name(s) exactly as on the deed.':'اتفقا شفهيًا على السعر وتاريخ الإغلاق والعربون، ثم قل إنك سترسل اتفاقية بسيطة للتوقيع اليوم. دوّن اسم البائع القانوني الكامل تمامًا كما في سند الملكية.',
    'Check the state':'تحقّق من الولاية',
    'Open the state’s sheet here. Make sure it is a title-company state, see which disclosures the seller must sign, and whether a wholesaling law applies.':'افتح ورقة الولاية هنا. تأكد أنها ولاية تُغلق فيها الصفقات عبر شركة ملكية، واطّلع على الإفصاحات التي يجب أن يوقّعها البائع، وهل ينطبق قانون للبيع بالجملة.',
    'Pull the details':'اجمع التفاصيل',
    'From the county site or the tax bill: owner names on title, parcel number and legal description. If the names don’t match the person you spoke to, stop and find out why before you send anything.':'من موقع المقاطعة أو فاتورة الضرائب: أسماء المالكين في السند ورقم القطعة والوصف القانوني. إن لم تطابق الأسماء الشخص الذي تحدثت معه، توقف واعرف السبب قبل إرسال أي شيء.',
    'Fill the agreement':'املأ الاتفاقية',
    'Pick “Cash purchase agreement” (or “Seller finance” if they are carrying the note), fill the boxes, and add the wholesaling disclosure addendum. Read it once top to bottom.':'اختر «Cash purchase agreement» (أو «Seller finance» إن كان البائع سيموّل)، واملأ الخانات، وأضف ملحق الإفصاح عن البيع بالجملة. اقرأها مرة كاملة من أولها إلى آخرها.',
    'Send it to sign':'أرسلها للتوقيع',
    'Save as PDF and send it through an e-sign app (free plans work for a few a month) or by email for a printed signature. Stay on the phone while they open it if you can.':'احفظها PDF وأرسلها عبر تطبيق توقيع إلكتروني (الخطط المجانية تكفي لبضع اتفاقيات شهريًا) أو بالبريد لتوقيع مطبوع. ابقَ على الهاتف أثناء فتحها إن أمكن.',
    'Open title':'افتح ملف الملكية',
    'Send the signed agreement to the title company the same day. Ask for the title commitment and the wire or check details for earnest money.':'أرسل الاتفاقية الموقّعة إلى شركة الملكية في اليوم نفسه. اطلب التزام الملكية وبيانات التحويل أو الشيك للعربون.',
    'Deposit earnest money':'أودِع العربون',
    'Send it within the days in the agreement and keep the receipt. Put the inspection deadline and closing date in the Deal CRM.':'أرسله خلال الأيام المذكورة في الاتفاقية واحتفظ بالإيصال. ضع موعد انتهاء الفحص وتاريخ الإغلاق في نظام الصفقات.',
    'Find the end buyer':'ابحث عن المشتري النهائي',
    'Use “Buyers who fit” in the Deal CRM. When a buyer commits, fill the Assignment of contract and collect their deposit before you tell anyone else it is sold.':'استخدم «المشترون المناسبون» في نظام الصفقات. عندما يلتزم مشترٍ، املأ عقد التنازل واستلم عربونه قبل أن تخبر أي أحد أنها بيعت.',
    'Title prepares the settlement statement. Check every number against the agreement and the assignment, then sign. Log the closed deal and the commission.':'تُعدّ شركة الملكية كشف التسوية. راجع كل رقم مقابل الاتفاقية والتنازل ثم وقّع. سجّل الصفقة المغلقة والعمولة.',
    'Date signed':'تاريخ التوقيع',
